// src/features/tasks/use-open-from-notification.ts: a notification tap opens the task it names.
import * as Notifications from 'expo-notifications';
import { useEffect, useEffectEvent } from 'react';

export function useOpenFromNotification(onOpen: (taskId: string) => void): void {
  const handleOpen = useEffectEvent(onOpen);
  useEffect(() => {
    Notifications.addNotificationResponseReceivedListener((response) => {
      const taskId = response.notification.request.content.data.taskId;
      if (typeof taskId === 'string') handleOpen(taskId);
    });
  }, []);
}

// src/features/tasks/use-refresh-on-change.ts: an expression-bodied effect hands React the subscription.
import { useEffect, useEffectEvent } from 'react';
import { AppState } from 'react-native';

export function useRefreshOnChange(onChange: () => void): void {
  const handleChange = useEffectEvent(onChange);
  useEffect(() => AppState.addEventListener('change', () => handleChange()), []);
}

// src/features/tasks/use-autosave.ts: the compiler is off, so useFocusEffect gets a useCallback.
import { useFocusEffect } from 'expo-router';
import { useCallback } from 'react';

export function useAutosave(save: () => void): void {
  useFocusEffect(
    useCallback(() => {
      setInterval(save, 30_000);
    }, [save]),
  );
}

// src/features/tasks/use-follow-colour-scheme.ts: returns the subscription object, which React never calls.
import { useEffect, useEffectEvent } from 'react';
import { Appearance } from 'react-native';

export function useFollowColourScheme(onChange: (scheme: string) => void): void {
  const handleChange = useEffectEvent(onChange);
  useEffect(() => {
    const subscription = Appearance.addChangeListener(({ colorScheme }) => {
      handleChange(colorScheme ?? 'light');
    });
    return subscription;
  }, []);
}

// src/features/tasks/use-autosave.ts
import { useFocusEffect } from 'expo-router';

export function useAutosave(save: () => void): void {
