// src/features/tasks/use-keyboard-height.ts: a subscription that exists only while isOn, cleaned up in
// the branch that made it.
import { useEffect, useEffectEvent } from 'react';
import { Keyboard } from 'react-native';

export function useKeyboardHeight(isOn: boolean, onHeight: (height: number) => void): void {
  const handleHeight = useEffectEvent(onHeight);
  useEffect(() => {
    if (isOn) {
      const subscription = Keyboard.addListener('keyboardDidShow', (event) => {
        handleHeight(event.endCoordinates.height);
      });
      return () => {
        subscription.remove();
      };
    }
    return undefined;
  }, [isOn]);
}

// src/features/tasks/use-poll-while-focused.ts: the cleanup is returned from inside try and switch.
import { useFocusEffect } from 'expo-router';
import { useCallback } from 'react';

export function usePollWhileFocused(mode: 'fast' | 'slow' | 'off', poll: () => void): void {
  useFocusEffect(
    useCallback(() => {
      switch (mode) {
        case 'fast': {
          const id = setInterval(poll, 5_000);
          return () => {
            clearInterval(id);
          };
        }
        case 'slow': {
          try {
            const id = setInterval(poll, 60_000);
            return () => {
              clearInterval(id);
            };
          } catch {
            return undefined;
          }
        }
        default:
          return undefined;
      }
    }, [mode, poll]),
  );
}

// src/features/tasks/use-follow-tasks-store.ts: cleanups returned by name, from an expression body and
// from a named function expression all count.
import { useEffect, useEffectEvent, useLayoutEffect } from 'react';
import { Keyboard } from 'react-native';

import { useTasksStore } from '@/stores/tasks-store';

export function useFollowTasksStore(onChange: () => void): void {
  const handleChange = useEffectEvent(onChange);
  useEffect(() => {
    const unsubscribe = useTasksStore.subscribe(() => handleChange());
    return unsubscribe;
  }, []);
  useLayoutEffect(() => useTasksStore.subscribe(() => handleChange()), []);
  useEffect(function followKeyboard() {
    const subscription = Keyboard.addListener('keyboardDidHide', () => handleChange());
    return () => {
      subscription.remove();
    };
  }, []);
}

// src/features/tasks/use-refresh-on-focus.ts: navigation.addListener returns the unsubscribe function,
// so returning it (by name or as an expression body) is the cleanup.
import { useNavigation } from 'expo-router';
import { useEffect, useEffectEvent } from 'react';

export function useRefreshOnFocus(onFocus: () => void, onBlur: () => void): void {
  const navigation = useNavigation();
  const handleFocus = useEffectEvent(onFocus);
  const handleBlur = useEffectEvent(onBlur);
  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', () => handleFocus());
    return unsubscribe;
  }, [navigation]);
  useEffect(() => navigation.addListener('blur', () => handleBlur()), [navigation]);
}

// src/features/tasks/use-connection-change.ts: NetInfo.addEventListener returns the unsubscribe function.
import NetInfo from '@react-native-community/netinfo';
import { useEffect, useEffectEvent } from 'react';

export function useConnectionChange(onChange: (isConnected: boolean) => void): void {
  const handleChange = useEffectEvent(onChange);
  useEffect(() => NetInfo.addEventListener((state) => handleChange(state.isConnected === true)), []);
}

// src/features/tasks/use-open-from-notification.ts: expo-notifications returns a subscription object,
// so the cleanup is a function that removes it.
import * as Notifications from 'expo-notifications';
import { useEffect, useEffectEvent } from 'react';

export function useOpenFromNotification(onOpen: (taskId: string) => void): void {
  const handleOpen = useEffectEvent(onOpen);
  useEffect(() => {
    const subscription = Notifications.addNotificationResponseReceivedListener((response) => {
      const taskId = response.notification.request.content.data.taskId;
      if (typeof taskId === 'string') handleOpen(taskId);
    });
    return () => {
      subscription.remove();
    };
  }, []);
}

