// src/features/settings/settings-sections.tsx: lists whose length is fixed by definition.
import { ScrollView, View } from 'react-native';

import { AppText } from '@/ui/app-text';

import type { ReactNode } from 'react';

const SECTIONS = ['general', 'notifications', 'about'] as const;
const LABELS = { general: 'General', about: 'About' } as const;

export type SettingsSectionsProps = {
  readonly values: readonly number[];
  readonly testID: string;
  readonly renderChart: (points: readonly number[]) => ReactNode;
};

export function SettingsSections({ values, testID, renderChart }: SettingsSectionsProps): ReactNode {
  return (
    <View testID={testID}>
      <ScrollView testID={`${testID}.list`}>
        {SECTIONS.map((section) => (
          <View key={section} testID={`${testID}.${section}`} />
        ))}
        {Object.entries(LABELS).map(([key, label]) => (
          <AppText key={key}>{label}</AppText>
        ))}
        {Array.from({ length: 3 }, (_, index) => (
          <View key={index} />
        ))}
        {renderChart(values.map((value) => value * 2))}
      </ScrollView>
      <ScrollView testID={`${testID}.empty`} />
    </View>
  );
}

